    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'

    def validate(v):
        if not re.match(pattern, v):
            raise ValueError(f"Invalid version string: {v}")

    validate(a)
    validate(b)

    def parse(v):
        # Split into core and optional pre-release/build
        match = re.match(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$', v)
        major, minor, patch = int(match.group(1)), int(match.group(2)), int(match.group(3))
        pre_release = match.group(4)
        # build metadata is ignored

        # Parse pre-release identifiers
        pre_ids = []
        if pre_release:
            for id_str in pre_release.split('.'):
                # Each identifier must be non-empty and made of ASCII letters, digits and '-'
                if not id_str or not re.match(r'^[A-Za-z0-9-]+$', id_str):
                    raise ValueError(f"Invalid pre-release identifier: {id_str}")
                # If all digits, must not have leading zero
                if id_str.isdigit():
                    if len(id_str) > 1 and id_str[0] == '0':
                        raise ValueError(f"Pre-release identifier with leading zero: {id_str}")
                    pre_ids.append(('num', int(id_str)))
                else:
                    pre_ids.append(('str', id_str))
        return (major, minor, patch, pre_ids)

    pa = parse(a)
    pb = parse(b)

    # Compare MAJOR, MINOR, PATCH
    for x, y in zip(pa[:3], pb[:3]):
        if x < y:
            return -1
        if x > y:
            return 1

    # Compare pre-release
    # A version with a pre-release is lower than the same version without one
    # pa[3] is pre_ids list, if empty means no pre-release

    # If one has pre-release and the other doesn't
    if len(pa[3]) == 0 and len(pb[3]) > 0:
        return -1  # a has no pre-release, b has -> a > b? Wait: "a version with a pre-release is lower than the same version without one"
        # So if a has pre-release and b doesn't, a < b -> return -1
        # If a doesn't have and b has, a > b -> return 1
    if len(pb[3]) == 0 and len(pa[3]) > 0:
        return 1

    # Both have pre-release or both don't
    if len(pa[3]) > 0 and len(pb[3]) > 0:
        # Compare identifier by identifier
        for id_a, id_b in zip(pa[3], pb[3]):
            type_a = id_a[0]
            type_b = id_b[0]

            if type_a == 'num' and type_b == 'num':
                if id_a[1] < id_b[1]:
                    return -1
                if id_a[1] > id_b[1]:
                    return 1
            elif type_a == 'str' and type_b == 'str':
                if id_a[1] < id_b[1]:
                    return -1
                if id_a[1] > id_b[1]:
                    return 1
            elif type_a == 'num' and type_b == 'str':
                # all-digit identifier is lower than any other
                return -1
            elif type_a == 'str' and type_b == 'num':
                return 1

        # If every shared identifier is equal, the one with more identifiers is higher
        if len(pa[3]) < len(pb[3]):
            return -1
        if len(pa[3]) > len(pb[3]):
            return 1

    # Equal
    return 0

